  "structured_data": {
    "regulations": [],
    "VTS/SSTS_references": {
      "knowledge": [
        {
          "name": "B级轿车风阻系数发展趋势",
          "content": "根据《Aerodynamics of Road Vehicles》中VW Golf案例，历代车型虽然正面面积Ax增加，但通过优化设计使Cd持续降低，同时升力显著下降以改善操控性。"
        },
        {
          "name": "纯电轿车空气动力学设计措施",
          "content": "成本有效的降阻措施包括：优化车尾流场、前保险杠导流、密封前脸结构、平整底盘、轮拱扰流等。高成本措施如主动进气格栅、全底盘护板、可调离地间隙等可进一步降低Cd。"
        }
      ],
      "rules": [
        {
          "name": "正投影面积估算规则",
          "content": "开发初期，正投影面积A可通过车高和车宽乘积乘以经验系数估算，sedan车型系数为0.85。",
          "formula": "A=high*wide*0.85"
        },
        {
          "name": "风阻系数目标值估算规则",
          "content": "对于纯电sedan车型，合理的Cd目标范围为(0.2, 0.26)。",
          "formula": "纯电sedan Cd∈（0.2,0.26）"
        },
        {
          "name": "冷却风阻系数估算规则",
          "content": "纯电车型的冷却风阻系数合理取值约为0.015。",
          "formula": "Cd_cool_air≈0.015"
        },
        {
          "name": "下车体及车轮附件风阻系数估算规则",
          "content": "具有完整底护板的纯电车型下车体风阻系数约为0.015；车轮轮辐开口风阻约为0.008~0.012，低风阻轮辋可降至0.002~0.003。",
          "formula": "下车体风阻≈0.015；车轮风阻≈0.008~0.012"
        },
        {
          "name": "升力系数目标值估算规则",
          "content": "普通乘用车的升力系数Cl应控制在0.1~0.15以下。",
          "formula": "Cl<0.1~0.15"
        }
      ],
      "cases": [
        {
          "name": "小鹏MONA M03风阻优化案例",
          "content": "同为A+级纯电sedan，长宽高4785*1896*1445mm，通过多轮风洞测试，最终达成Cd=0.208。其早期油泥模型Cd最小值约0.19，可作为类似尺寸车型的工程极限参考。"
        }
      ]
    }
  },
  "reasoning_logic": "根据知识图谱，明确了VTS/SSTS指标间的构成关系。向量库检索提供了B级轿车风阻发展趋势和通用设计措施。规则库提供了针对纯电sedan车型的各项指标（正投影面积、风阻系数、各SSTS分项、升力系数）的具体估算公式和目标范围。案例库提供了同级别纯电sedan（小鹏MONA M03）的实际开发数据作为对标参考。由于问题聚焦于目标值定义而非法规合规，且未检索到直接相关的强制性国家标准或行业标准对风阻/升力系数设定限值，因此法规部分留空。"
}
